import 'package:dio/dio.dart';import '../core/api_exceptions.dart';import '../models/genre.dart';import '../models/page_result.dart';import '../models/publisher.dart';import '../models/reader.dart';import '../models/simple_query.dart';import 'genre_repository.dart';import 'publisher_repository.dart';import 'reader_repository.dart';
Map<String,dynamic> _qp(SimpleQuery q)=>{if(q.search.trim().isNotEmpty)'search':q.search.trim(),'sort':'${q.sortField},${q.sortAscending?'asc':'desc'}','page':q.page,'size':q.size,if(q.includeDeleted)'includeDeleted':true};PageResult<T> _page<T>(dynamic raw,T Function(Map<String,dynamic>) parse,int fallback){final d=Map<String,dynamic>.from(raw as Map);return PageResult(items:(d['items']as List? ?? []).whereType<Map>().map((e)=>parse(Map<String,dynamic>.from(e))).toList(),page:d['page']as int? ?? 1,size:d['size']as int? ?? fallback,total:d['total']as int? ?? 0);}
class ApiGenreRepository implements GenreRepository{final Dio dio;List<Genre>?cache;ApiGenreRepository(this.dio);@override Future<PageResult<Genre>>find(SimpleQuery q)=>retryRead(()=>guard(()async=>_page((await dio.get('/genres',queryParameters:_qp(q))).data,Genre.fromJson,q.size)));@override Future<Genre?>findById(int id)=>retryRead(()=>guard(()async=>Genre.fromJson(Map<String,dynamic>.from((await dio.get('/genres/$id')).data as Map))));@override Future<List<Genre>>allActive()async=>cache??=(await find(const SimpleQuery(size:50))).items;void c()=>cache=null;@override Future<Genre>create(Genre v)=>guard(()async{final x=Genre.fromJson(Map<String,dynamic>.from((await dio.post('/genres',data:{'name':v.name,'description':v.description})).data as Map));c();return x;});@override Future<Genre>update(Genre v)=>guard(()async{final x=Genre.fromJson(Map<String,dynamic>.from((await dio.put('/genres/${v.id}',data:{'name':v.name,'description':v.description})).data as Map));c();return x;});@override Future<void>softDelete(int id)=>guard(()async{await dio.delete('/genres/$id');c();});@override Future<void>hardDelete(int id)=>guard(()async{await dio.delete('/genres/$id',queryParameters:{'hard':true});c();});@override Future<void>restore(int id)=>guard(()async{await dio.post('/genres/$id/restore');c();});@override Future<int>deleteMany(List<int>ids)=>guard(()async{final r=await dio.post('/genres/bulk-delete',data:{'ids':ids});c();return(r.data as Map)['deleted']as int? ?? 0;});}
class ApiPublisherRepository implements PublisherRepository{final Dio dio;List<Publisher>?cache;ApiPublisherRepository(this.dio);@override Future<PageResult<Publisher>>find(SimpleQuery q)=>retryRead(()=>guard(()async=>_page((await dio.get('/publishers',queryParameters:_qp(q))).data,Publisher.fromJson,q.size)));@override Future<Publisher?>findById(int id)=>retryRead(()=>guard(()async=>Publisher.fromJson(Map<String,dynamic>.from((await dio.get('/publishers/$id')).data as Map))));@override Future<List<Publisher>>allActive()async=>cache??=(await find(const SimpleQuery(size:50))).items;void c()=>cache=null;@override Future<Publisher>create(Publisher v)=>guard(()async{final x=Publisher.fromJson(Map<String,dynamic>.from((await dio.post('/publishers',data:{'name':v.name,'country':v.country})).data as Map));c();return x;});@override Future<Publisher>update(Publisher v)=>guard(()async{final x=Publisher.fromJson(Map<String,dynamic>.from((await dio.put('/publishers/${v.id}',data:{'name':v.name,'country':v.country})).data as Map));c();return x;});@override Future<void>softDelete(int id)=>guard(()async{await dio.delete('/publishers/$id');c();});@override Future<void>hardDelete(int id)=>guard(()async{await dio.delete('/publishers/$id',queryParameters:{'hard':true});c();});@override Future<void>restore(int id)=>guard(()async{await dio.post('/publishers/$id/restore');c();});@override Future<int>deleteMany(List<int>ids)=>guard(()async{final r=await dio.post('/publishers/bulk-delete',data:{'ids':ids});c();return(r.data as Map)['deleted']as int? ?? 0;});}
class ApiReaderRepository implements ReaderRepository{final Dio dio;ApiReaderRepository(this.dio);Map<String,dynamic>w(Reader v)=>{'fullName':v.fullName,'email':v.email,'phone':v.phone,'card':v.card.toJson()};@override Future<PageResult<Reader>>find(SimpleQuery q)=>retryRead(()=>guard(()async=>_page((await dio.get('/readers',queryParameters:_qp(q))).data,Reader.fromJson,q.size)));@override Future<Reader?>findById(int id)=>retryRead(()=>guard(()async=>Reader.fromJson(Map<String,dynamic>.from((await dio.get('/readers/$id')).data as Map))));@override Future<Reader>create(Reader v)=>guard(()async=>Reader.fromJson(Map<String,dynamic>.from((await dio.post('/readers',data:w(v))).data as Map)));@override Future<Reader>update(Reader v)=>guard(()async=>Reader.fromJson(Map<String,dynamic>.from((await dio.put('/readers/${v.id}',data:w(v))).data as Map)));@override Future<void>softDelete(int id)=>guard(()async{await dio.delete('/readers/$id');});@override Future<void>hardDelete(int id)=>guard(()async{await dio.delete('/readers/$id',queryParameters:{'hard':true});});@override Future<void>restore(int id)=>guard(()async{await dio.post('/readers/$id/restore');});@override Future<int>deleteMany(List<int>ids)=>guard(()async{final r=await dio.post('/readers/bulk-delete',data:{'ids':ids});return(r.data as Map)['deleted']as int? ?? 0;});}
